/**
 * @file font.h
 * @brief Built-in 8x14 bitmap font (Terminus): glyph size and glyph lookup.
 * @ingroup gfx
 *
 * Each glyph is #FONT_HEIGHT bytes, one per row from the top. In each byte, bit 7 is the
 * leftmost pixel and a set bit is a foreground pixel; only the top #FONT_WIDTH bits are
 * used. The data comes from gfx/terminus_14.inc, generated by tools/bdf2inc.py.
 *
 * Characters are indexed by byte value, read as Latin-1 (U+0000 to U+00FF). Glyphs exist
 * for 0x00 (a box shape), 0x20-0x7E and 0xA0-0xFF; every other byte value has an empty
 * glyph, so it draws as a blank cell.
 */
#pragma once

#include <stdint.h>

/// @brief Glyph width in pixels; the glyph data has this size, so changing it alone breaks it
#define FONT_WIDTH 8 // native size, tied to the glyph data
/// @brief Glyph height in pixels, which is also the number of bytes per glyph
#define FONT_HEIGHT 14

/**
 * @brief Returns the bitmap of a character.
 *
 * Every byte value is valid (see the file description for which ones are blank).
 *
 * @param c Character, as a Latin-1 byte
 *
 * @return Pointer to #FONT_HEIGHT bytes in read-only static storage; never NULL. The caller
 *         must not free or modify it.
 */
const uint8_t* font_get_glyph(unsigned char c);